insert into public.categories (slug, name, summary, description, illustration, sort_order) values ('mekanik-salmastralar', 'Mekanik Salmastralar', 'Pompa, mikser ve kompresörler için O-ringli, körüklü ve özel tip mekanik salmastralar.', 'Mekanik salmastralar, dönen mil ile sabit gövde arasındaki sızdırmazlığı birbirine hassas biçimde lepleme ile düzlenmiş iki yüzey sayesinde sağlar. EN 12756 (DIN 24960) ölçülerindeki standart tiplerden özel imalatlara kadar geniş bir yelpazede, akışkana ve çalışma koşullarına uygun malzeme kombinasyonlarıyla tedarik ediyoruz.', 'seal-multispring', 0) on conflict (slug) do nothing;
insert into public.categories (parent_id, slug, name, summary, description, illustration, sort_order) values ((select id from public.categories where slug = 'mekanik-salmastralar'), 'o-ringli-salmastralar', 'O-Ringli Salmastralar', 'Konik, çok yaylı ve dalga yaylı; dengeli ve dengesiz itmeli (pusher) tipler.', null, 'seal-multispring', 0) on conflict (slug) do nothing;
insert into public.categories (parent_id, slug, name, summary, description, illustration, sort_order) values ((select id from public.categories where slug = 'mekanik-salmastralar'), 'elastomer-koruklu-salmastralar', 'Elastomer Körüklü Salmastralar', 'Su, atık su ve hafif kimyasallar için ekonomik, milin aşınmasını önleyen körüklü tipler.', null, 'seal-elastomer-bellows', 10) on conflict (slug) do nothing;
insert into public.categories (parent_id, slug, name, summary, description, illustration, sort_order) values ((select id from public.categories where slug = 'mekanik-salmastralar'), 'metal-koruklu-salmastralar', 'Metal Körüklü Salmastralar', 'Yüksek sıcaklık ve kimyasal dayanım gerektiren prosesler için elastomersiz dinamik yapı.', null, 'seal-metal-bellows', 20) on conflict (slug) do nothing;
insert into public.categories (parent_id, slug, name, summary, description, illustration, sort_order) values ((select id from public.categories where slug = 'mekanik-salmastralar'), 'ozel-tip-salmastralar', 'Özel Tip Salmastralar', 'Çamur, yüksek basınç ve ayrık (split) uygulamalar için özel tasarımlar.', null, 'seal-split', 30) on conflict (slug) do nothing;
insert into public.categories (slug, name, summary, description, illustration, sort_order) values ('kartus-salmastralar', 'Kartuş Salmastralar', 'Fabrikada ayarlı, montajı kolay tek ve çift kartuş salmastralar.', 'Kartuş salmastralar; salmastra, burç ve flanşın tek ünite halinde, fabrikada ayarlanmış olarak teslim edildiği sistemlerdir. Montaj hatalarını ortadan kaldırır, bakım süresini kısaltır ve pompa değişikliği gerektirmeden tek veya çift salmastra düzenine geçişi mümkün kılar.', 'seal-cartridge', 10) on conflict (slug) do nothing;
insert into public.categories (slug, name, summary, description, illustration, sort_order) values ('mikser-salmastralari', 'Mikser Salmastraları', 'Reaktör, karıştırıcı ve tanklar için DIN 28138 uyumlu tek, çift ve kuru çalışan salmastralar.', 'Karıştırıcı ve reaktörlerde mil salgısı, düşük devir ve gaz fazı gibi pompalardan farklı koşullar vardır. Rulman destekli, kartuş tipli mikser salmastralarımız sıvı veya gaz yağlamalı olarak tek ve çift düzenlerde sunulur.', 'seal-agitator', 20) on conflict (slug) do nothing;
insert into public.categories (slug, name, summary, description, illustration, sort_order) values ('oem-pompa-salmastralari', 'OEM Pompa Salmastraları', 'Yaygın pompa markaları için birebir ölçüde muadil salmastralar.', 'Orijinal ölçü ve montaj şekline birebir uyan muadil salmastralarla yedek parça maliyetini ve bekleme süresini düşürün. Pompa marka ve modelini ya da eski salmastranın fotoğrafını göndermeniz yeterli. Marka adları yalnızca uyumluluğu belirtmek amacıyla kullanılmıştır.', 'seal-cartridge', 30) on conflict (slug) do nothing;
insert into public.categories (slug, name, summary, description, illustration, sort_order) values ('doner-baglanti-elemanlari', 'Döner Bağlantı Elemanları', 'Su, buhar, kızgın yağ, hava ve hidrolik için döner başlıklar (rotary joint).', 'Döner başlıklar, dönen silindir ve millere akışkanın sızdırmadan iletilmesini sağlar. Kâğıt, tekstil, plastik, kauçuk ve metal işleme sektörlerinde tek ve çift akışlı, sifonlu ve vakum kırıcılı modeller sunuyoruz.', 'rotary-joint', 40) on conflict (slug) do nothing;
insert into public.categories (parent_id, slug, name, summary, description, illustration, sort_order) values ((select id from public.categories where slug = 'doner-baglanti-elemanlari'), 'su-basliklari', 'Su Başlıkları', 'Soğutma ve proses suyu için tek ve çift akışlı başlıklar.', null, 'rotary-joint', 0) on conflict (slug) do nothing;
insert into public.categories (parent_id, slug, name, summary, description, illustration, sort_order) values ((select id from public.categories where slug = 'doner-baglanti-elemanlari'), 'buhar-basliklari', 'Buhar Başlıkları', 'Kurutma silindirleri için sifonlu ve vakum kırıcılı buhar başlıkları.', null, 'rotary-joint-double', 10) on conflict (slug) do nothing;
insert into public.categories (parent_id, slug, name, summary, description, illustration, sort_order) values ((select id from public.categories where slug = 'doner-baglanti-elemanlari'), 'kizgin-yag-basliklari', 'Kızgın Yağ Başlıkları', '350 °C''ye kadar ısı transfer yağı uygulamaları.', null, 'rotary-joint-double', 20) on conflict (slug) do nothing;
insert into public.categories (parent_id, slug, name, summary, description, illustration, sort_order) values ((select id from public.categories where slug = 'doner-baglanti-elemanlari'), 'hava-hidrolik-basliklari', 'Hava, Hidrolik ve Soğutma Başlıkları', 'Pnömatik, hidrolik ve yüksek devirli soğutma sıvısı başlıkları.', null, 'rotary-joint', 30) on conflict (slug) do nothing;
insert into public.categories (slug, name, summary, description, illustration, sort_order) values ('swivel-joint', 'Swivel Joint (Döner Mafsal)', 'Dolum-boşaltım kolları ve hortum hatları için bilyalı döner mafsallar.', 'Swivel joint''ler, boru hatlarında 360° serbest dönüş sağlayarak dolum kolları, hortum makaraları ve esnek bağlantılarda hattın burulmasını önler.', 'swivel-joint', 50) on conflict (slug) do nothing;
insert into public.categories (slug, name, summary, description, illustration, sort_order) values ('tampon-sivi-sistemleri', 'Tampon Sıvı Sistemleri', 'Çift salmastralar için API 682 planlarına uygun basınçlandırma ve soğutma üniteleri.', 'Çift mekanik salmastraların güvenli çalışması için bariyer veya tampon sıvının basıncı, sıcaklığı ve seviyesi kontrol altında tutulmalıdır. API 682 planlarına uygun tank ve akümülatör sistemleri tasarlıyor ve tedarik ediyoruz.', 'seal-support-vessel', 60) on conflict (slug) do nothing;
insert into public.categories (slug, name, summary, description, illustration, sort_order) values ('yumusak-salmastralar', 'Yumuşak Salmastralar', 'Pompa, vana ve karıştırıcılar için PTFE, grafit, aramid ve cam elyaf örgü salmastralar.', 'Örgü (yumuşak) salmastralar; pompa, vana, karıştırıcı ve kırıcılarda ekonomik ve kolay uygulanabilir sızdırmazlık sağlar. Kare kesitli örgüler 3 mm''den 30 mm''ye kadar kesitlerde, makara veya ölçüye kesilmiş halka olarak tedarik edilir.', 'packing-ptfe', 70) on conflict (slug) do nothing;
insert into public.categories (slug, name, summary, description, illustration, sort_order) values ('ptfe-urunleri', 'PTFE Ürünleri', 'PTFE levha, çubuk, boru ve genleşmiş PTFE conta bantları.', 'PTFE; neredeyse tüm kimyasallara dayanımı, düşük sürtünme katsayısı ve geniş sıcaklık aralığıyla sızdırmazlık uygulamalarının temel malzemesidir. Saf ve dolgulu (cam, karbon, bronz, grafit) kalitelerde yarı mamul ve işlenmiş parça sunuyoruz.', 'ptfe', 80) on conflict (slug) do nothing;
insert into public.categories (slug, name, summary, description, illustration, sort_order) values ('conta-ve-levhalar', 'Conta ve Levhalar', 'Asbestsiz, grafit ve kauçuk conta levhaları; spiral sargılı ve ölçüye kesilmiş contalar.', 'Flanş ve kapak sızdırmazlığı için asbestsiz lifli, esnek grafit ve kauçuk levhaları stoktan tedarik ediyor, çizime veya numuneye göre hassas kesim yapıyoruz.', 'gasket-sheet', 90) on conflict (slug) do nothing;
insert into public.categories (slug, name, summary, description, illustration, sort_order) values ('o-ringler', 'O-Ringler', 'NBR, FKM, EPDM, silikon, FFKM ve FEP kaplı O-ringler.', 'Standart (ISO 3601, AS568, JIS) ve özel ölçülerde O-ringleri akışkana ve sıcaklığa uygun elastomer seçimiyle tedarik ediyoruz. Mekanik salmastra yedek O-ring setleri de hazırlanır.', 'o-ring-nbr', 100) on conflict (slug) do nothing;
insert into public.categories (slug, name, summary, description, illustration, sort_order) values ('karbon-ve-yuzey-urunleri', 'Karbon ve Yüzey Ürünleri', 'Mekanik salmastra yedek yüzleri: karbon, SiC, TC ve seramik halkalar; karbon burçlar.', 'Mekanik salmastraların aşınan yüzeylerini çizime veya numuneye göre üretiyor, lepleme ile ışık bandı düzlemselliğinde teslim ediyoruz.', 'seal-face-carbon', 110) on conflict (slug) do nothing;
insert into public.categories (slug, name, summary, description, illustration, sort_order) values ('lepleme', 'Lepleme', 'Lepleme makineleri, elmas süspansiyonlar ve düzlemsellik ölçüm ekipmanları.', 'Salmastra yüzeylerinin yenilenmesi için lepleme makineleri, sarf malzemeleri ve optik düzlemsellik kontrol ekipmanları. Yüzey yenileme hizmeti de veriyoruz.', 'lapping', 120) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'o-ringli-salmastralar'), 'ks-m2', 'KS-M2', 'KS-M2 Konik Yaylı Salmastra', 'Küçük mil çapları için konik yaylı, dengesiz, tek yönlü ekonomik salmastra.', 'KS-M2, tek konik yayla yüzey baskısını sağlayan kompakt bir O-ringli salmastradır. Az sayıda parçadan oluşan yapısı sayesinde küçük sirkülasyon ve santrifüj pompalarda güvenilir ve ekonomik bir çözüm sunar. Konik yay, dönüş yönüne bağlı çalışır; sağ ve sol yönlü olarak tedarik edilir.', '[{"label":"Mil çapı (d1)","value":"6 … 38 mm"},{"label":"Basınç (p1)","value":"≤ 10 bar"},{"label":"Sıcaklık (t)","value":"−20 … +140 °C"},{"label":"Kayma hızı (vg)","value":"≤ 15 m/s"},{"label":"Eksenel hareket","value":"±1,0 mm"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit (reçine / antimon emdirilmiş)","Silisyum karbür (SiC)","Tungsten karbür (TC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Tungsten karbür (TC)","Alümina seramik (Al₂O₃)","Karbon grafit"]},{"part":"Sekonder conta (O-ring)","options":["NBR","EPDM","FKM","FFKM","VMQ (silikon)","FEP kaplı FKM"]},{"part":"Yay ve metal parçalar","options":["AISI 316 (1.4401)","Hastelloy® C-4 (opsiyonel)"]}]'::jsonb, array['Tek, dengesiz, O-ringli itmeli (pusher) tip','Konik yay — dönüş yönüne bağlı','Kirliliğe karşı toleranslı basit yapı','Az parça, kolay montaj']::text[], array['Sirkülasyon pompaları','Temiz ve hafif kirli su','Soğutma suyu devreleri','Düşük katı içerikli akışkanlar']::text[], array[]::text[], array['EagleBurgmann M2N','Tip M2']::text[], array['su-ve-atik-su','enerji']::text[], 'seal-conical', false, 0) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'o-ringli-salmastralar'), 'ks-m3', 'KS-M3', 'KS-M3 Konik Yaylı Salmastra', '6–80 mm aralığında konik yaylı, genel amaçlı O-ringli salmastra.', 'KS-M3, konik yaylı dengesiz salmastraların en yaygın kullanılan tipidir. Geniş mil çapı aralığı, sade yapısı ve farklı yüzey malzemesi seçenekleriyle su, yağ ve hafif kimyasallarda uzun ömürlü çalışır. Yüzey ve O-ring malzemeleri akışkana göre seçilir.', '[{"label":"Mil çapı (d1)","value":"6 … 80 mm"},{"label":"Basınç (p1)","value":"≤ 10 bar"},{"label":"Sıcaklık (t)","value":"−20 … +140 °C"},{"label":"Kayma hızı (vg)","value":"≤ 15 m/s"},{"label":"Eksenel hareket","value":"±1,0 mm"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit (reçine / antimon emdirilmiş)","Silisyum karbür (SiC)","Tungsten karbür (TC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Tungsten karbür (TC)","Alümina seramik (Al₂O₃)","Karbon grafit"]},{"part":"Sekonder conta (O-ring)","options":["NBR","EPDM","FKM","FFKM","VMQ (silikon)","FEP kaplı FKM"]},{"part":"Yay ve metal parçalar","options":["AISI 316 (1.4401)","Hastelloy® C-4 (opsiyonel)"]}]'::jsonb, array['Konik yay, dönüş yönüne bağlı','Sağ / sol dönüşlü seçenek','Geniş malzeme kombinasyonu','Ekonomik yedek parça']::text[], array['Santrifüj pompalar','Su ve atık su','Yağlar ve hafif kimyasallar','Tarımsal sulama pompaları']::text[], array[]::text[], array['EagleBurgmann M3N','Tip M3']::text[], array['su-ve-atik-su','kimya-ve-petrokimya','enerji']::text[], 'seal-conical', true, 10) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'o-ringli-salmastralar'), 'ks-m7', 'KS-M7', 'KS-M7 Çok Yaylı Salmastra (EN 12756)', 'EN 12756 ölçülerinde, dönüş yönünden bağımsız çok yaylı dengesiz salmastra.', 'KS-M7, dönen yüzey tutucusu içindeki çok sayıda küçük yay ile yüzey üzerinde eşit baskı dağılımı sağlar. Dönüş yönünden bağımsızdır ve EN 12756 (DIN 24960) KU/NU montaj ölçülerine uygundur. Değiştirilebilir yüzeyleri ve geniş malzeme seçenekleri sayesinde proses pompalarında standart çözümdür.', '[{"label":"Mil çapı (d1)","value":"14 … 100 mm"},{"label":"Basınç (p1)","value":"≤ 25 bar"},{"label":"Sıcaklık (t)","value":"−50 … +220 °C"},{"label":"Kayma hızı (vg)","value":"≤ 20 m/s"},{"label":"Eksenel hareket","value":"d1 ≤ 25 mm: ±1,0 mm · d1 28 … 63 mm: ±1,5 mm · d1 ≥ 65 mm: ±2,0 mm"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit (reçine / antimon emdirilmiş)","Silisyum karbür (SiC)","Tungsten karbür (TC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Tungsten karbür (TC)","Alümina seramik (Al₂O₃)","Karbon grafit"]},{"part":"Sekonder conta (O-ring)","options":["NBR","EPDM","FKM","FFKM","VMQ (silikon)","FEP kaplı FKM"]},{"part":"Yay ve metal parçalar","options":["AISI 316 (1.4401)","Hastelloy® C-4 (opsiyonel)"]}]'::jsonb, array['Çok yaylı, dönüş yönünden bağımsız','EN 12756 KU / NU ölçüleri','Akışkandan korunmuş yaylar (opsiyon)','Değiştirilebilir yüzeyler']::text[], array['Kimya ve petrokimya pompaları','Kazan besleme ve kondensat','Gıda ve içecek prosesleri','Denizcilik uygulamaları']::text[], array['EN 12756 (DIN 24960)']::text[], array['EagleBurgmann M7N','Tip M7']::text[], array['kimya-ve-petrokimya','gida-ve-icecek','denizcilik','enerji']::text[], 'seal-multispring', true, 20) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'o-ringli-salmastralar'), 'ks-m74d', 'KS-M74D', 'KS-M74D Çift Salmastra', 'Arka arkaya (back-to-back) düzenli, çok yaylı çift mekanik salmastra.', 'KS-M74D, iki adet çok yaylı salmastranın bariyer sıvısıyla birlikte çalıştığı çift düzendir. Toksik, yanıcı, kristalleşen veya yağlama özelliği zayıf akışkanlarda ürünün atmosfere kaçmasını önler. Tandem ve arka arkaya düzenlerde tedarik edilir.', '[{"label":"Mil çapı (d1)","value":"18 … 200 mm"},{"label":"Basınç (p1)","value":"≤ 25 bar"},{"label":"Sıcaklık (t)","value":"−50 … +220 °C"},{"label":"Kayma hızı (vg)","value":"≤ 20 m/s"},{"label":"Eksenel hareket","value":"d1 ≤ 100 mm: ±0,5 mm · d1 > 100 mm: ±2,0 mm"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit (reçine / antimon emdirilmiş)","Silisyum karbür (SiC)","Tungsten karbür (TC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Tungsten karbür (TC)","Alümina seramik (Al₂O₃)","Karbon grafit"]},{"part":"Sekonder conta (O-ring)","options":["NBR","EPDM","FKM","FFKM","VMQ (silikon)","FEP kaplı FKM"]},{"part":"Yay ve metal parçalar","options":["AISI 316 (1.4401)","Hastelloy® C-4 (opsiyonel)"]}]'::jsonb, array['Çift salmastra — bariyer sıvısı ile','Dönüş yönünden bağımsız','API Plan 52 / 53 ile uyumlu','Sıfır emisyon hedefli uygulamalar']::text[], array['Toksik ve yanıcı akışkanlar','Kristalleşen ürünler','Vakum altında çalışan pompalar','Reaktör besleme pompaları']::text[], array['EN 12756 (DIN 24960)']::text[], array['EagleBurgmann M74-D']::text[], array['kimya-ve-petrokimya','ilac']::text[], 'seal-double', false, 30) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'o-ringli-salmastralar'), 'ks-h7', 'KS-H7', 'KS-H7 Dengeli Çok Yaylı Salmastra', '80 bar''a kadar basınçlar için dengeli (balanced), EN 12756 ölçülerinde salmastra.', 'KS-H7, kademeli mil veya burç üzerinde çalışan dengeli bir salmastradır. Dengeleme sayesinde yüzeylerdeki kapanma kuvveti basınçtan büyük ölçüde bağımsız kalır; bu da yüksek basınçta düşük ısınma ve uzun ömür sağlar. Rafineri, petrokimya ve enerji santrallerinde yaygın olarak kullanılır.', '[{"label":"Mil çapı (d1)","value":"14 … 200 mm"},{"label":"Basınç (p1)","value":"d1 14 … 100 mm: ≤ 80 bar · d1 100 … 200 mm: ≤ 25 bar"},{"label":"Sıcaklık (t)","value":"−50 … +220 °C"},{"label":"Kayma hızı (vg)","value":"≤ 20 m/s"},{"label":"Eksenel hareket","value":"d1 ≤ 22 mm: ±1,0 mm · d1 24 … 58 mm: ±1,5 mm · d1 ≥ 60 mm: ±2,0 mm"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit (reçine / antimon emdirilmiş)","Silisyum karbür (SiC)","Tungsten karbür (TC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Tungsten karbür (TC)","Alümina seramik (Al₂O₃)","Karbon grafit"]},{"part":"Sekonder conta (O-ring)","options":["NBR","EPDM","FKM","FFKM","VMQ (silikon)","FEP kaplı FKM"]},{"part":"Yay ve metal parçalar","options":["AISI 316 (1.4401)","Hastelloy® C-4 (opsiyonel)"]}]'::jsonb, array['Dengeli (balanced) tasarım','Çok yaylı, dönüş yönünden bağımsız','Yüksek basınçta düşük ısı üretimi','EN 12756 KB / NB ölçüleri']::text[], array['Kazan besleme pompaları','Hidrokarbon ve solventler','Yüksek basınçlı proses pompaları','Sıcak su devreleri']::text[], array['EN 12756 (DIN 24960)']::text[], array['EagleBurgmann H7N','Tip H7']::text[], array['kimya-ve-petrokimya','enerji']::text[], 'seal-multispring', true, 40) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'o-ringli-salmastralar'), 'ks-h74d', 'KS-H74D', 'KS-H74D Dengeli Çift Salmastra', 'Yüksek basınçlı ve tehlikeli akışkanlar için dengeli çift salmastra.', 'KS-H74D, iki dengeli salmastranın bariyer sıvısı ile çalıştığı çift düzendir. Basınçlı bariyer sisteminde ürün tarafı basıncının yüksek olduğu tehlikeli proseslerde emniyetli sızdırmazlık sağlar.', '[{"label":"Mil çapı (d1)","value":"14 … 200 mm"},{"label":"Basınç (p1)","value":"d1 ≤ 100 mm: ≤ 80 bar · d1 100 … 200 mm: ≤ 25 bar"},{"label":"Sıcaklık (t)","value":"−50 … +220 °C"},{"label":"Kayma hızı (vg)","value":"≤ 20 m/s"},{"label":"Eksenel hareket","value":"d1 ≤ 100 mm: ±0,5 mm · d1 > 100 mm: ±2,0 mm"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit (reçine / antimon emdirilmiş)","Silisyum karbür (SiC)","Tungsten karbür (TC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Tungsten karbür (TC)","Alümina seramik (Al₂O₃)","Karbon grafit"]},{"part":"Sekonder conta (O-ring)","options":["NBR","EPDM","FKM","FFKM","VMQ (silikon)","FEP kaplı FKM"]},{"part":"Yay ve metal parçalar","options":["AISI 316 (1.4401)","Hastelloy® C-4 (opsiyonel)"]}]'::jsonb, array['Dengeli çift salmastra','Basınçlı bariyer sıvısı ile çalışma','Dönüş yönünden bağımsız','API Plan 53A/B/C uyumlu']::text[], array['Hidrokarbonlar','Yüksek basınçlı reaktör besleme','Sıvılaştırılmış gazlar','Tehlikeli kimyasallar']::text[], array['EN 12756 (DIN 24960)']::text[], array['EagleBurgmann H74-D']::text[], array['kimya-ve-petrokimya','enerji']::text[], 'seal-double', false, 50) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'o-ringli-salmastralar'), 'ks-h12', 'KS-H12', 'KS-H12 Dengeli Konik Yaylı Salmastra', 'Konik yaylı, dengeli, EN 12756 ölçülerinde kompakt salmastra.', 'KS-H12, konik yay yapısının sadeliğini dengeli tasarımın basınç avantajıyla birleştirir. Kademeli mil gerektirir; orta basınçlı proses ve sıcak su pompalarında ekonomik bir dengeli salmastra çözümüdür.', '[{"label":"Mil çapı (d1)","value":"10 … 80 mm"},{"label":"Basınç (p1)","value":"≤ 25 bar"},{"label":"Sıcaklık (t)","value":"−50 … +220 °C"},{"label":"Kayma hızı (vg)","value":"≤ 15 m/s"},{"label":"Eksenel hareket","value":"±1,0 mm"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit (reçine / antimon emdirilmiş)","Silisyum karbür (SiC)","Tungsten karbür (TC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Tungsten karbür (TC)","Alümina seramik (Al₂O₃)","Karbon grafit"]},{"part":"Sekonder conta (O-ring)","options":["NBR","EPDM","FKM","FFKM","VMQ (silikon)","FEP kaplı FKM"]},{"part":"Yay ve metal parçalar","options":["AISI 316 (1.4401)","Hastelloy® C-4 (opsiyonel)"]}]'::jsonb, array['Dengeli tasarım','Konik yay, dönüş yönüne bağlı','Kompakt montaj boyu','EN 12756 ölçüleri']::text[], array['Sıcak su pompaları','Isıtma devreleri','Orta basınçlı proses pompaları']::text[], array['EN 12756 (DIN 24960)']::text[], array['EagleBurgmann H12N']::text[], array['enerji','kimya-ve-petrokimya']::text[], 'seal-conical', false, 60) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'o-ringli-salmastralar'), 'ks-hj92', 'KS-HJ92', 'KS-HJ92 Korumalı Yaylı Salmastra', 'Yayları akışkandan korunmuş, viskoz ve kirli ortamlar için dengeli salmastra.', 'KS-HJ92''de yaylar akışkanla temas etmeyecek şekilde gövde içinde korunur. Böylece lifli, yapışkan, kristalleşen veya katı içeren akışkanlarda yayların tıkanması önlenir. Kâğıt, şeker ve atık su endüstrisinde tercih edilir.', '[{"label":"Mil çapı (d1)","value":"18 … 100 mm"},{"label":"Basınç (p1)","value":"≤ 25 bar"},{"label":"Sıcaklık (t)","value":"−20 … +180 °C"},{"label":"Kayma hızı (vg)","value":"≤ 10 m/s"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit (reçine / antimon emdirilmiş)","Silisyum karbür (SiC)","Tungsten karbür (TC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Tungsten karbür (TC)","Alümina seramik (Al₂O₃)","Karbon grafit"]},{"part":"Sekonder conta (O-ring)","options":["NBR","EPDM","FKM","FFKM","VMQ (silikon)","FEP kaplı FKM"]},{"part":"Yay ve metal parçalar","options":["AISI 316 (1.4401)","Hastelloy® C-4 (opsiyonel)"]}]'::jsonb, array['Akışkandan korunmuş yaylar','Dengeli tasarım','Tıkanmaya karşı dayanıklı','Dönüş yönünden bağımsız']::text[], array['Kâğıt hamuru ve lifli akışkanlar','Şeker şurubu ve melas','Çamur ve atık su','Boya ve lateks']::text[], array[]::text[], array['EagleBurgmann HJ92N']::text[], array['kagit-ve-seluloz','seker','su-ve-atik-su']::text[], 'seal-multispring', false, 70) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'o-ringli-salmastralar'), 'ks-h75', 'KS-H75', 'KS-H75 Ağır Hizmet Dengeli Salmastra', '40 bar''a kadar, yüksek eksenel harekete izin veren ağır hizmet salmastrası.', 'KS-H75, rafineri ve enerji pompalarında karşılaşılan yüksek basınç, sıcaklık ve eksenel harekete göre tasarlanmış dengeli bir salmastradır. Sabit yay yapısıyla yüksek devirlerde de kararlı çalışır.', '[{"label":"Mil çapı (d1)","value":"20 … 110 mm"},{"label":"Basınç (p1)","value":"≤ 40 bar"},{"label":"Sıcaklık (t)","value":"−40 … +220 °C"},{"label":"Kayma hızı (vg)","value":"≤ 23 m/s"},{"label":"Eksenel hareket","value":"±2,0 … 4,0 mm (çapa bağlı)"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit (reçine / antimon emdirilmiş)","Silisyum karbür (SiC)","Tungsten karbür (TC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Tungsten karbür (TC)","Alümina seramik (Al₂O₃)","Karbon grafit"]},{"part":"Sekonder conta (O-ring)","options":["NBR","EPDM","FKM","FFKM","VMQ (silikon)","FEP kaplı FKM"]},{"part":"Yay ve metal parçalar","options":["AISI 316 (1.4401)","Hastelloy® C-4 (opsiyonel)"]}]'::jsonb, array['Dengeli, ağır hizmet tipi','Yüksek eksenel hareket toleransı','Yüksek devirlerde kararlı','API uyumlu malzeme seçenekleri']::text[], array['Rafineri proses pompaları','Kazan besleme','Sıcak hidrokarbonlar']::text[], array[]::text[], array['EagleBurgmann H75VN']::text[], array['kimya-ve-petrokimya','enerji']::text[], 'seal-multispring', false, 80) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'elastomer-koruklu-salmastralar'), 'ks-mg1', 'KS-MG1', 'KS-MG1 Elastomer Körüklü Salmastra', 'Mil üzerinde kaymayan elastomer körük sayesinde mili aşındırmayan, dünyada en yaygın salmastra tiplerinden biri.', 'KS-MG1, dönen yüzeyi taşıyan elastomer körük ve körüğü saran konik yaydan oluşur. Körük mil üzerinde kaymadığından mil aşınması (fretting) oluşmaz. Temiz su, atık su, soğutma sıvıları ve hafif kimyasallarda uzun ömür sunar. EN 12756 KU montaj ölçüsüne uygun versiyonu mevcuttur.', '[{"label":"Mil çapı (d1)","value":"10 … 100 mm"},{"label":"Basınç (p1)","value":"≤ 16 bar · vakum ≤ 0,5 bar (yatak kilitli 1 bar)"},{"label":"Sıcaklık (t)","value":"−20 … +140 °C"},{"label":"Kayma hızı (vg)","value":"≤ 10 m/s"},{"label":"Eksenel hareket","value":"±2,0 mm"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit","Silisyum karbür (SiC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Alümina seramik (Al₂O₃)","Tungsten karbür (TC)"]},{"part":"Körük","options":["NBR","EPDM","FKM"]},{"part":"Yay ve metal parçalar","options":["AISI 304","AISI 316"]}]'::jsonb, array['Dönüş yönünden bağımsız','Mili aşındırmayan körük yapısı','Mil salgısı ve eksenel harekete toleranslı','EN 12756 uyumlu versiyon']::text[], array['Temiz ve atık su','Dalgıç pompalar','Soğutma sıvıları','Havuz ve sulama pompaları']::text[], array['EN 12756 (KU)']::text[], array['EagleBurgmann MG1','Tip MG1']::text[], array['su-ve-atik-su','gida-ve-icecek','denizcilik']::text[], 'seal-elastomer-bellows', true, 90) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'elastomer-koruklu-salmastralar'), 'ks-mg12', 'KS-MG12', 'KS-MG12 Elastomer Körüklü Salmastra', 'Silindirik yaylı, kısa montaj boylu elastomer körüklü salmastra.', 'KS-MG12, silindirik yay ile elastomer körüğün birlikte çalıştığı kompakt bir salmastradır. Kısa montaj boyu gerektiren sirkülasyon ve blok pompalarda tercih edilir; ayna yüzeyi farklı malzemelerle kombine edilebilir.', '[{"label":"Mil çapı (d1)","value":"10 … 100 mm"},{"label":"Basınç (p1)","value":"≤ 12 bar · vakum ≤ 0,5 bar"},{"label":"Sıcaklık (t)","value":"−20 … +140 °C"},{"label":"Kayma hızı (vg)","value":"≤ 10 m/s"},{"label":"Eksenel hareket","value":"±0,5 mm"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit","Silisyum karbür (SiC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Alümina seramik (Al₂O₃)","Tungsten karbür (TC)"]},{"part":"Körük","options":["NBR","EPDM","FKM"]},{"part":"Yay ve metal parçalar","options":["AISI 304","AISI 316"]}]'::jsonb, array['Silindirik yay','Kısa montaj boyu','Dönüş yönünden bağımsız','Ekonomik yedek parça']::text[], array['Blok ve sirkülasyon pompaları','Isıtma ve soğutma devreleri','Su ve glikol karışımları']::text[], array['EN 12756 (KU, kısa versiyon)']::text[], array['EagleBurgmann MG12 / MG912']::text[], array['su-ve-atik-su','enerji']::text[], 'seal-elastomer-bellows', false, 100) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'elastomer-koruklu-salmastralar'), 'ks-mg13', 'KS-MG13', 'KS-MG13 Elastomer Körüklü Salmastra', 'EN 12756 uzun montaj boyuna uygun, silindirik yaylı elastomer körüklü salmastra.', 'KS-MG13, KS-MG12 ile aynı çalışma prensibine sahip, EN 12756 KU uzun montaj boyuna uygun versiyondur. Standart norm pompalarda mevcut salmastranın doğrudan yerine kullanılabilir.', '[{"label":"Mil çapı (d1)","value":"10 … 100 mm"},{"label":"Basınç (p1)","value":"≤ 12 bar · vakum ≤ 0,5 bar"},{"label":"Sıcaklık (t)","value":"−20 … +140 °C"},{"label":"Kayma hızı (vg)","value":"≤ 10 m/s"},{"label":"Eksenel hareket","value":"±0,5 mm"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit","Silisyum karbür (SiC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Alümina seramik (Al₂O₃)","Tungsten karbür (TC)"]},{"part":"Körük","options":["NBR","EPDM","FKM"]},{"part":"Yay ve metal parçalar","options":["AISI 304","AISI 316"]}]'::jsonb, array['EN 12756 KU montaj boyu','Silindirik yay','Dönüş yönünden bağımsız']::text[], array['Norm pompalar','Su ve atık su','Hafif kimyasallar']::text[], array['EN 12756 (KU)']::text[], array['EagleBurgmann MG13 / MG913']::text[], array['su-ve-atik-su','kimya-ve-petrokimya']::text[], 'seal-elastomer-bellows', false, 110) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'elastomer-koruklu-salmastralar'), 'ks-21', 'KS-21', 'KS-21 Elastomer Körüklü Salmastra (Tip 21)', 'Metal kovanlı elastomer körüklü, inç ve metrik ölçülerde genel amaçlı salmastra.', 'KS-21, metal bir kovanla desteklenmiş elastomer körük ve silindirik yaydan oluşan klasik bir tasarımdır. Beyaz eşya, ev tipi ve hafif endüstriyel pompalarda, sirkülasyon ve sulama pompalarında yaygın olarak kullanılır.', '[{"label":"Mil çapı (d1)","value":"6 … 70 mm (inç ölçüler mevcut)"},{"label":"Basınç (p1)","value":"≤ 6 bar · vakum ≤ 0,5 bar"},{"label":"Sıcaklık (t)","value":"−20 … +120 °C"},{"label":"Kayma hızı (vg)","value":"≤ 10 m/s"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit","Silisyum karbür (SiC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Alümina seramik (Al₂O₃)","Tungsten karbür (TC)"]},{"part":"Körük","options":["NBR","EPDM","FKM"]},{"part":"Yay ve metal parçalar","options":["AISI 304","AISI 316"]}]'::jsonb, array['Metal kovanlı körük','Dönüş yönünden bağımsız','İnç ve metrik ölçüler','Stoktan hızlı teslim']::text[], array['Sirkülasyon ve hidrofor pompaları','Sulama pompaları','Beyaz eşya ve ev tipi pompalar']::text[], array[]::text[], array['Tip 21','EagleBurgmann BT-AR']::text[], array['su-ve-atik-su']::text[], 'seal-elastomer-bellows', false, 120) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'elastomer-koruklu-salmastralar'), 'ks-560', 'KS-560', 'KS-560 Kompakt Körüklü Salmastra', 'Küçük pompalar için kauçuk körüklü, düşük basınçlı kompakt salmastra.', 'KS-560, küçük mil çaplarında sade ve ekonomik bir sızdırmazlık çözümüdür. Kauçuk körük, yüzey ve yay tek ünite halinde monte edilir; küçük santrifüj ve dalgıç pompalar için idealdir.', '[{"label":"Mil çapı (d1)","value":"8 … 50 mm"},{"label":"Basınç (p1)","value":"≤ 7 bar · vakum ≤ 0,1 bar"},{"label":"Sıcaklık (t)","value":"−20 … +100 °C"},{"label":"Kayma hızı (vg)","value":"≤ 5 m/s"},{"label":"Eksenel hareket","value":"±1,0 mm"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit","Silisyum karbür (SiC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Alümina seramik (Al₂O₃)","Tungsten karbür (TC)"]},{"part":"Körük","options":["NBR","EPDM","FKM"]},{"part":"Yay ve metal parçalar","options":["AISI 304","AISI 316"]}]'::jsonb, array['Kompakt ve hafif','Tek ünite montaj','Ekonomik']::text[], array['Küçük santrifüj pompalar','Dalgıç drenaj pompaları','Yıkama makinesi pompaları']::text[], array[]::text[], array['Tip 560','EagleBurgmann EA560']::text[], array['su-ve-atik-su']::text[], 'seal-elastomer-bellows', false, 130) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'metal-koruklu-salmastralar'), 'ks-mfl85', 'KS-MFL85', 'KS-MFL85 Metal Körüklü Salmastra', 'Kaynaklı metal körüklü, sabit tip, dönüş yönünden bağımsız salmastra.', 'KS-MFL85''te yay görevini kaynaklı metal körük üstlenir; dinamik O-ring bulunmaz. Bu sayede O-ring kaynaklı yapışma ve aşınma sorunları ortadan kalkar, geniş kimyasal ve sıcaklık aralığında çalışılabilir. Sıcak su, hidrokarbon ve polimerleşen akışkanlarda tercih edilir.', '[{"label":"Mil çapı (d1)","value":"16 … 100 mm"},{"label":"Basınç (p1)","value":"Dıştan basınçlı ≤ 25 bar · içten basınçlı ≤ 10 bar (<120 °C), ≤ 5 bar (<220 °C)"},{"label":"Sıcaklık (t)","value":"−40 … +220 °C"},{"label":"Kayma hızı (vg)","value":"≤ 20 m/s"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit","Silisyum karbür (SiC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Tungsten karbür (TC)"]},{"part":"Metal körük","options":["Hastelloy® C-276","AM 350","Inconel® 718"]},{"part":"Sekonder conta","options":["FKM","FFKM","Esnek grafit (yüksek sıcaklık)"]}]'::jsonb, array['Dinamik O-ring yok','Kaynaklı metal körük','Dönüş yönünden bağımsız','Kendi kendini temizleyen körük hareketi']::text[], array['Sıcak su ve kondensat','Hidrokarbonlar','Polimerleşen akışkanlar','Yüksek sıcaklıklı prosesler']::text[], array[]::text[], array['EagleBurgmann MFL85N']::text[], array['kimya-ve-petrokimya','enerji']::text[], 'seal-metal-bellows', true, 140) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'metal-koruklu-salmastralar'), 'ks-mbs100', 'KS-MBS100', 'KS-MBS100 Metal Körüklü Salmastra', 'Dönen metal körüklü, EN 12756 ölçülerine uygun salmastra.', 'KS-MBS100, dönen metal körük yapısıyla standart pompalarda O-ringli salmastraların doğrudan yerine kullanılabilen bir metal körüklü salmastradır. Kimya ve proses pompalarında kararlı performans sunar.', '[{"label":"Mil çapı (d1)","value":"20 … 100 mm"},{"label":"Basınç (p1)","value":"≤ 25 bar (Q1/Q1 kombinasyonunda ≤ 16 bar)"},{"label":"Sıcaklık (t)","value":"−40 … +220 °C (Q1/Q1: +160 °C)"},{"label":"Kayma hızı (vg)","value":"≤ 20 m/s"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit","Silisyum karbür (SiC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Tungsten karbür (TC)"]},{"part":"Metal körük","options":["Hastelloy® C-276","AM 350","Inconel® 718"]},{"part":"Sekonder conta","options":["FKM","FFKM","Esnek grafit (yüksek sıcaklık)"]}]'::jsonb, array['Dönen metal körük','EN 12756 ölçülerine uygun','Dönüş yönünden bağımsız']::text[], array['Kimya proses pompaları','Solventler','Sıcak yağlar']::text[], array['EN 12756']::text[], array['EagleBurgmann MBS100']::text[], array['kimya-ve-petrokimya']::text[], 'seal-metal-bellows', false, 150) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'metal-koruklu-salmastralar'), 'ks-mf95', 'KS-MF95', 'KS-MF95 Metal Körüklü Salmastra', 'EN 12756 ölçülerinde dönen metal körüklü, kompakt salmastra.', 'KS-MF95, dönen metal körüklü kompakt yapısıyla standart norm pompalara uyar. Kimyasal dayanımı yüksek körük malzemesi sayesinde agresif akışkanlarda güvenle kullanılabilir.', '[{"label":"Mil çapı (d1)","value":"14 … 100 mm"},{"label":"Basınç (p1)","value":"≤ 16 bar"},{"label":"Sıcaklık (t)","value":"−40 … +220 °C"},{"label":"Kayma hızı (vg)","value":"≤ 20 m/s"},{"label":"Eksenel hareket","value":"±0,5 mm"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit","Silisyum karbür (SiC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Tungsten karbür (TC)"]},{"part":"Metal körük","options":["Hastelloy® C-276","AM 350","Inconel® 718"]},{"part":"Sekonder conta","options":["FKM","FFKM","Esnek grafit (yüksek sıcaklık)"]}]'::jsonb, array['Dönen metal körük','EN 12756 ölçüleri','Kompakt yapı']::text[], array['Norm kimya pompaları','Asit ve alkaliler','Sıcak su']::text[], array['EN 12756']::text[], array['EagleBurgmann MF95N']::text[], array['kimya-ve-petrokimya']::text[], 'seal-metal-bellows', false, 160) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'metal-koruklu-salmastralar'), 'ks-mflwt', 'KS-MFLWT', 'KS-MFLWT Yüksek Sıcaklık Metal Körüklü Salmastra', 'Isı transfer yağları için +400 °C''ye kadar metal körüklü salmastra.', 'KS-MFLWT, ısı transfer yağları ve sıcak hidrokarbonlar için geliştirilmiş, esnek grafit sekonder contalı metal körüklü bir salmastradır. Elastomer içermeyen yapısı yüksek sıcaklıklarda güvenli çalışma sağlar.', '[{"label":"Mil çapı (d1)","value":"16 … 150 mm"},{"label":"Basınç (p1)","value":"Dıştan basınçlı ≤ 25 bar · içten basınçlı ≤ 10 bar (<120 °C), ≤ 5 bar (<220 °C), ≤ 3 bar (<400 °C)"},{"label":"Sıcaklık (t)","value":"−20 … +400 °C"},{"label":"Kayma hızı (vg)","value":"≤ 20 m/s"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit","Silisyum karbür (SiC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Tungsten karbür (TC)"]},{"part":"Metal körük","options":["Hastelloy® C-276","AM 350","Inconel® 718"]},{"part":"Sekonder conta","options":["FKM","FFKM","Esnek grafit (yüksek sıcaklık)"]}]'::jsonb, array['Elastomersiz tasarım','Esnek grafit sekonder conta','+400 °C''ye kadar','Sabit yatak kilitli']::text[], array['Kızgın yağ (termal yağ) pompaları','Sıcak bitüm ve asfalt','Sıcak hidrokarbonlar']::text[], array[]::text[], array['EagleBurgmann MFLWT']::text[], array['tekstil','kimya-ve-petrokimya','enerji']::text[], 'seal-metal-bellows', false, 170) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'metal-koruklu-salmastralar'), 'ks-mfl65', 'KS-MFL65', 'KS-MFL65 Yüksek Hız Metal Körüklü Salmastra', '50 m/s kayma hızına ve +400 °C''ye kadar sabit metal körüklü salmastra.', 'KS-MFL65, sabit metal körük yapısı sayesinde yüksek devirli ve yüksek sıcaklıklı uygulamalarda kararlı çalışır. Rafineri ve petrokimya proseslerinde API uyumlu malzemelerle tedarik edilir.', '[{"label":"Mil çapı (d1)","value":"16 … 100 mm (daha büyük çaplar talebe göre)"},{"label":"Basınç (p1)","value":"Dıştan basınçlı ≤ 25 bar · içten basınçlı ≤ 10 / 5 / 3 bar (120 / 220 / 400 °C)"},{"label":"Sıcaklık (t)","value":"−20 … +400 °C"},{"label":"Kayma hızı (vg)","value":"≤ 50 m/s"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit","Silisyum karbür (SiC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Tungsten karbür (TC)"]},{"part":"Metal körük","options":["Hastelloy® C-276","AM 350","Inconel® 718"]},{"part":"Sekonder conta","options":["FKM","FFKM","Esnek grafit (yüksek sıcaklık)"]}]'::jsonb, array['Sabit metal körük','Yüksek kayma hızı','Yüksek sıcaklık','Sabit yatak kilitli']::text[], array['Rafineri pompaları','Sıcak hidrokarbonlar','Yüksek devirli pompalar']::text[], array[]::text[], array['EagleBurgmann MFL65']::text[], array['kimya-ve-petrokimya','enerji']::text[], 'seal-metal-bellows', false, 180) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'ozel-tip-salmastralar'), 'ks-hr', 'KS-HR', 'KS-HR Çamur Tipi Salmastra', 'Katı içerikli ve aşındırıcı akışkanlar için ağır hizmet salmastrası.', 'KS-HR, çamur, maden ve kum içeren akışkanlarda çalışan pompalar için tasarlanmıştır. Aşınmaya dayanıklı SiC/SiC yüzeyleri ve akışkandan korunmuş yay yapısı sayesinde zorlu ortamlarda uzun ömür sağlar.', '[{"label":"Mil çapı (dN)","value":"36 … 270 mm"},{"label":"Basınç (p1)","value":"≤ 16 bar"},{"label":"Sıcaklık (t)","value":"−20 … +160 °C"},{"label":"Kayma hızı (vg)","value":"≤ 10 m/s"}]'::jsonb, '[{"part":"Yüzeyler","options":["SiC / SiC","TC / TC"]},{"part":"Sekonder conta (O-ring)","options":["NBR","EPDM","FKM","FFKM","VMQ (silikon)","FEP kaplı FKM"]},{"part":"Metal parçalar","options":["AISI 316","Duplex paslanmaz"]}]'::jsonb, array['Aşındırıcı akışkanlara dayanıklı','Korunmuş yaylar','Geniş katı toleransı','Vakumda quench bağlantısı']::text[], array['Çamur pompaları','Maden ve cevher işleme','Kum ve çakıl yıkama','Baca gazı desülfürizasyonu']::text[], array[]::text[], array['EagleBurgmann HR serisi']::text[], array['su-ve-atik-su','demir-celik','enerji']::text[], 'seal-cartridge', false, 190) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'ozel-tip-salmastralar'), 'ks-split', 'KS-SPLIT', 'KS-SPLIT Ayrık (Split) Salmastra', 'Pompayı sökmeden monte edilebilen, iki parçalı kartuş salmastra.', 'KS-SPLIT, tüm parçaları ikiye bölünmüş olarak üretilir; bu sayede motor ve pompa sökülmeden, mil üzerinde montaj yapılabilir. Büyük çaplı pompa, mikser ve pervane millerinde bakım süresini günlerden saatlere indirir.', '[{"label":"Mil çapı (d1)","value":"50 … 150 mm"},{"label":"Basınç (p1)","value":"≤ 10 bar"},{"label":"Sıcaklık (t)","value":"−40 … +150 °C (80 °C üzerinde yıkama önerilir)"},{"label":"Kayma hızı (vg)","value":"≤ 10 m/s"},{"label":"Eksenel / radyal hareket","value":"±1,5 mm / ±0,8 mm"}]'::jsonb, '[{"part":"Yüzeyler","options":["Karbon / SiC","SiC / SiC"]},{"part":"Sekonder conta (O-ring)","options":["NBR","EPDM","FKM","FFKM","VMQ (silikon)","FEP kaplı FKM"]},{"part":"Metal parçalar","options":["AISI 316"]}]'::jsonb, array['Pompa sökülmeden montaj','Tamamen ayrık yapı','Büyük mil çapları','Kısa duruş süresi']::text[], array['Büyük santrifüj pompalar','Mikserler ve pervaneler','Kâğıt makineleri','Gemi pervane milleri']::text[], array[]::text[], array['EagleBurgmann Splitex']::text[], array['kagit-ve-seluloz','su-ve-atik-su','denizcilik']::text[], 'seal-split', false, 200) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'kartus-salmastralar'), 'ks-cs', 'KS-CS', 'KS-CS Tek Kartuş Salmastra', 'Fabrikada ayarlı, dengeli, tek kartuş salmastra — norm pompalar için standart çözüm.', 'KS-CS; salmastra, burç, flanş ve ayar klipsleriyle birlikte tek ünite olarak teslim edilir. Montajda ölçü alma ve ayar gerekmez; klipsler çıkarıldıktan sonra salmastra çalışmaya hazırdır. Dengeli tasarımı ve farklı flanş seçenekleriyle ISO 2858 / ISO 5199 pompalarına uyar.', '[{"label":"Mil çapı (d1)","value":"25 … 100 mm (diğer ölçüler talebe göre)"},{"label":"Basınç (p1)","value":"Karbon/SiC: ≤ 25 bar · SiC/SiC: ≤ 12 bar"},{"label":"Sıcaklık (t)","value":"−40 … +220 °C (O-ring dayanımına bağlı)"},{"label":"Kayma hızı (vg)","value":"Karbon/SiC: ≤ 16 m/s · SiC/SiC: ≤ 10 m/s"},{"label":"Eksenel hareket","value":"±1,0 mm (d1 ≥ 75 mm: ±1,5 mm)"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit (reçine / antimon emdirilmiş)","Silisyum karbür (SiC)","Tungsten karbür (TC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Tungsten karbür (TC)","Alümina seramik (Al₂O₃)","Karbon grafit"]},{"part":"Sekonder conta (O-ring)","options":["NBR","EPDM","FKM","FFKM","VMQ (silikon)","FEP kaplı FKM"]},{"part":"Yay ve metal parçalar","options":["AISI 316 (1.4401)","Hastelloy® C-4 (opsiyonel)"]}]'::jsonb, array['Fabrikada ayarlı, montaja hazır','Dengeli, dönüş yönünden bağımsız','Yıkama (flush) ve quench bağlantıları','Norm pompalara uygun flanşlar']::text[], array['Kimya proses pompaları','Kâğıt ve selüloz','Su ve atık su','Gıda ve içecek']::text[], array['ISO 2858 / ISO 5199 pompalarına uygun']::text[], array['EagleBurgmann Cartex-SN']::text[], array['kimya-ve-petrokimya','kagit-ve-seluloz','su-ve-atik-su','gida-ve-icecek']::text[], 'seal-cartridge', true, 210) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'kartus-salmastralar'), 'ks-csq', 'KS-CSQ', 'KS-CSQ Quench''li Tek Kartuş Salmastra', 'Atmosfer tarafında dudak conta veya kısma burcuyla quench uygulamalı tek kartuş salmastra.', 'KS-CSQ, tek kartuş salmastranın atmosfer tarafına dudak conta (Q) veya kısma burcu (T) eklenmiş versiyonudur. Kristalleşen, havayla reaksiyona giren veya soğutulması gereken akışkanlarda quench sıvısı veya buharı ile güvenli çalışma sağlar.', '[{"label":"Mil çapı (d1)","value":"25 … 100 mm"},{"label":"Basınç (p1)","value":"≤ 25 bar"},{"label":"Sıcaklık (t)","value":"−40 … +220 °C"},{"label":"Kayma hızı (vg)","value":"≤ 16 m/s"},{"label":"Quench basıncı","value":"Basınçsız (≤ 0,5 bar)"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit (reçine / antimon emdirilmiş)","Silisyum karbür (SiC)","Tungsten karbür (TC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Tungsten karbür (TC)","Alümina seramik (Al₂O₃)","Karbon grafit"]},{"part":"Sekonder conta (O-ring)","options":["NBR","EPDM","FKM","FFKM","VMQ (silikon)","FEP kaplı FKM"]},{"part":"Yay ve metal parçalar","options":["AISI 316 (1.4401)","Hastelloy® C-4 (opsiyonel)"]}]'::jsonb, array['Dudak contalı veya kısma burçlu quench','Kristalleşme ve kurumaya karşı koruma','Fabrikada ayarlı']::text[], array['Şeker çözeltileri','Kostik ve kristalleşen ürünler','Sıcak akışkanlar']::text[], array[]::text[], array['EagleBurgmann Cartex-QN / TN']::text[], array['seker','kimya-ve-petrokimya']::text[], 'seal-cartridge', false, 220) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'kartus-salmastralar'), 'ks-cd', 'KS-CD', 'KS-CD Çift Kartuş Salmastra', 'Bariyer sıvısı ile çalışan, fabrikada ayarlı çift kartuş salmastra.', 'KS-CD, iki salmastranın tek kartuş ünitede birleştirildiği, basınçlı bariyer sıvısı ile çalışan bir sistemdir. Tehlikeli, toksik veya aşındırıcı akışkanlarda ürünün atmosfere kaçmasını engeller. Dahili pompalama halkası bariyer sıvısının dolaşımını sağlar.', '[{"label":"Mil çapı (d1)","value":"25 … 100 mm"},{"label":"Basınç (p1)","value":"Karbon/SiC: ≤ 25 bar · SiC/SiC: ≤ 20 bar"},{"label":"Bariyer basıncı (p3)","value":"≤ 25 bar · ideal Δp (p3 − p1) = 2 … 3 bar"},{"label":"Sıcaklık (t)","value":"−40 … +220 °C"},{"label":"Kayma hızı (vg)","value":"≤ 16 m/s"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit (reçine / antimon emdirilmiş)","Silisyum karbür (SiC)","Tungsten karbür (TC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Tungsten karbür (TC)","Alümina seramik (Al₂O₃)","Karbon grafit"]},{"part":"Sekonder conta (O-ring)","options":["NBR","EPDM","FKM","FFKM","VMQ (silikon)","FEP kaplı FKM"]},{"part":"Yay ve metal parçalar","options":["AISI 316 (1.4401)","Hastelloy® C-4 (opsiyonel)"]}]'::jsonb, array['Çift salmastra, tek kartuş','Dahili pompalama halkası','API Plan 53A/B/C ve 54 uyumlu','Fabrikada basınç testli']::text[], array['Toksik ve yanıcı akışkanlar','Solventler','Polimer ve reçineler','Vakum pompaları']::text[], array[]::text[], array['EagleBurgmann Cartex-DN']::text[], array['kimya-ve-petrokimya','ilac']::text[], 'seal-cartridge-double', true, 230) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'kartus-salmastralar'), 'ks-mtx', 'KS-MTX', 'KS-MTX Kompakt Kartuş Salmastra', 'EN 12756 salmastra boşluklarına sığan, kompakt tek kartuş salmastra.', 'KS-MTX, standart EN 12756 salmastra boşluğunda pompa üzerinde değişiklik gerektirmeden kullanılabilen kompakt bir kartuş salmastradır. Montaj kolaylığını dar yerlerde de mümkün kılar.', '[{"label":"Mil çapı (d1)","value":"25 … 80 mm"},{"label":"Basınç (p1)","value":"≤ 25 bar"},{"label":"Sıcaklık (t)","value":"−40 … +220 °C (O-ring dayanımına bağlı)"},{"label":"Kayma hızı (vg)","value":"≤ 20 m/s"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit (reçine / antimon emdirilmiş)","Silisyum karbür (SiC)","Tungsten karbür (TC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Tungsten karbür (TC)","Alümina seramik (Al₂O₃)","Karbon grafit"]},{"part":"Sekonder conta (O-ring)","options":["NBR","EPDM","FKM","FFKM","VMQ (silikon)","FEP kaplı FKM"]},{"part":"Yay ve metal parçalar","options":["AISI 316 (1.4401)","Hastelloy® C-4 (opsiyonel)"]}]'::jsonb, array['Kompakt kartuş','Pompa değişikliği gerektirmez','Dönüş yönünden bağımsız']::text[], array['Norm pompalar','Blok pompalar','Proses pompaları']::text[], array['EN 12756 boşluklarına uygun']::text[], array['EagleBurgmann Mtex']::text[], array['kimya-ve-petrokimya','su-ve-atik-su']::text[], 'seal-cartridge', false, 240) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'kartus-salmastralar'), 'ks-mtxd', 'KS-MTXD', 'KS-MTXD Kompakt Çift Kartuş Salmastra', 'Standart salmastra boşluğuna sığan kompakt çift kartuş salmastra.', 'KS-MTXD, kompakt kartuş yapısını çift salmastra güvenliğiyle birleştirir. Bariyer sıvısı sistemleriyle birlikte, dar salmastra boşluklarında bile tehlikeli akışkanların sızdırmazlığını sağlar.', '[{"label":"Mil çapı (d1)","value":"25 … 80 mm"},{"label":"Basınç (p1)","value":"≤ 25 bar"},{"label":"Bariyer basıncı (p3)","value":"≤ 16 bar · ideal Δp = 2 … 3 bar"},{"label":"Sıcaklık (t)","value":"−40 … +220 °C"},{"label":"Kayma hızı (vg)","value":"≤ 20 m/s"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit (reçine / antimon emdirilmiş)","Silisyum karbür (SiC)","Tungsten karbür (TC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Tungsten karbür (TC)","Alümina seramik (Al₂O₃)","Karbon grafit"]},{"part":"Sekonder conta (O-ring)","options":["NBR","EPDM","FKM","FFKM","VMQ (silikon)","FEP kaplı FKM"]},{"part":"Yay ve metal parçalar","options":["AISI 316 (1.4401)","Hastelloy® C-4 (opsiyonel)"]}]'::jsonb, array['Kompakt çift kartuş','API Plan 52 / 53 / 54 uyumlu','Pompa değişikliği gerektirmez']::text[], array['Tehlikeli kimyasallar','Sıcak akışkanlar','Solventler']::text[], array[]::text[], array['EagleBurgmann Mtex-D']::text[], array['kimya-ve-petrokimya']::text[], 'seal-cartridge-double', false, 250) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'kartus-salmastralar'), 'ks-knv', 'KS-KNV', 'KS-KNV Salmastra Konvertörü', 'Örgü salmastralı pompaları mekanik salmastraya dönüştüren adaptör kiti.', 'KS-KNV, örgü salmastra kutusuna sahip eski pompaların salmastra kutusu işlenmeden kartuş mekanik salmastraya dönüştürülmesini sağlar. Pompa ölçüleri yerinde alınarak projelendirilir; su kaybını ve bakım ihtiyacını büyük ölçüde azaltır.', '[{"label":"Uygulama","value":"Örgü salmastra kutulu pompalar"},{"label":"Mil çapı","value":"Pompaya göre projelendirilir"},{"label":"Malzeme","value":"AISI 316 flanş ve burç"}]'::jsonb, '[{"part":"Flanş ve burç","options":["AISI 316","Duplex paslanmaz"]},{"part":"Sekonder conta (O-ring)","options":["NBR","EPDM","FKM","FFKM","VMQ (silikon)","FEP kaplı FKM"]}]'::jsonb, array['Pompa gövdesinde işleme gerektirmez','Kartuş salmastra ile uyumlu','Yerinde ölçü ve projelendirme']::text[], array['Eski tip su pompaları','Kâğıt ve selüloz pompaları','Sirkülasyon pompaları']::text[], array[]::text[], array[]::text[], array['su-ve-atik-su','kagit-ve-seluloz']::text[], 'seal-cartridge', false, 260) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'mikser-salmastralari'), 'ks-ag1', 'KS-AG1', 'KS-AG1 Tek Mikser Salmastrası (DIN 28138)', 'Üstten tahrikli karıştırıcılar için rulmanlı, tek kartuş mikser salmastrası.', 'KS-AG1, DIN 28138 bağlantı ölçülerine uygun, entegre rulmanlı kartuş tipi bir mikser salmastrasıdır. Rulman, mil salgısını salmastra yüzeylerinden uzak tutar. Basınçsız veya düşük basınçlı tanklarda, quench sistemiyle birlikte kullanılır.', '[{"label":"Mil çapı (d3)","value":"40 … 220 mm"},{"label":"Basınç (p1)","value":"vakum … 6 bar"},{"label":"Sıcaklık (t)","value":"−40 … +150 °C (soğutma flanşıyla +250 °C)"},{"label":"Kayma hızı (vg)","value":"0 … 5 m/s"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit (reçine / antimon emdirilmiş)","Silisyum karbür (SiC)","Tungsten karbür (TC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Tungsten karbür (TC)","Alümina seramik (Al₂O₃)","Karbon grafit"]},{"part":"Sekonder conta (O-ring)","options":["NBR","EPDM","FKM","FFKM","VMQ (silikon)","FEP kaplı FKM"]},{"part":"Yay ve metal parçalar","options":["AISI 316 (1.4401)","Hastelloy® C-4 (opsiyonel)"]}]'::jsonb, array['DIN 28138 bağlantı ölçüleri','Entegre rulman','Kartuş tasarım','Quench bağlantısı']::text[], array['Karıştırıcı tankları','Reaktörler','Depolama tankları']::text[], array['DIN 28138 T2']::text[], array['EagleBurgmann M481']::text[], array['kimya-ve-petrokimya','ilac','gida-ve-icecek']::text[], 'seal-agitator', true, 270) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'mikser-salmastralari'), 'ks-ag2', 'KS-AG2', 'KS-AG2 Çift Mikser Salmastrası (DIN 28138)', 'Basınçlı reaktörler için bariyer sıvılı çift mikser salmastrası.', 'KS-AG2, iki salmastranın bariyer sıvısı ile çalıştığı, entegre rulmanlı çift mikser salmastrasıdır. Basınçlı reaktörlerde tehlikeli buharların ve ürünün atmosfere çıkmasını önler; tampon sıvı sistemleriyle birlikte kullanılır.', '[{"label":"Mil çapı (d3)","value":"40 … 220 mm"},{"label":"Basınç (p1)","value":"vakum … 16 bar"},{"label":"Bariyer basıncı (p3)","value":"≤ 18 bar"},{"label":"Sıcaklık (t)","value":"−40 … +200 °C (özel tasarımda +350 °C)"},{"label":"Kayma hızı (vg)","value":"0 … 5 m/s"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit (reçine / antimon emdirilmiş)","Silisyum karbür (SiC)","Tungsten karbür (TC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Tungsten karbür (TC)","Alümina seramik (Al₂O₃)","Karbon grafit"]},{"part":"Sekonder conta (O-ring)","options":["NBR","EPDM","FKM","FFKM","VMQ (silikon)","FEP kaplı FKM"]},{"part":"Yay ve metal parçalar","options":["AISI 316 (1.4401)","Hastelloy® C-4 (opsiyonel)"]}]'::jsonb, array['Çift salmastra','Entegre rulman','Tampon sıvı sistemi ile uyumlu','Soğutma flanşı seçeneği']::text[], array['Basınçlı reaktörler','Polimerizasyon','Hidrojenasyon']::text[], array['DIN 28138 T2']::text[], array['EagleBurgmann M481 (çift)','M461']::text[], array['kimya-ve-petrokimya','ilac']::text[], 'seal-agitator', false, 280) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'mikser-salmastralari'), 'ks-agdry', 'KS-AGDRY', 'KS-AGDRY Kuru Çalışan Mikser Salmastrası', 'Sıvı yağlama gerektirmeyen, gaz fazında çalışan mikser salmastrası.', 'KS-AGDRY, özel karbon yüzey malzemesi sayesinde yağlama sıvısı olmadan kuru çalışır. Bariyer sıvısının ürüne karışmasının istenmediği gıda, ilaç ve toz karıştırıcılarında temiz bir çözüm sunar.', '[{"label":"Mil çapı (d1)","value":"25 … 160 mm"},{"label":"Basınç (p1)","value":"vakum … 6 bar"},{"label":"Sıcaklık (t)","value":"−20 … +150 °C (soğutma flanşıyla +250 °C)"},{"label":"Kayma hızı (vg)","value":"0 … 2 m/s"},{"label":"Eksenel / radyal hareket","value":"±1,5 mm / ±1,5 mm"}]'::jsonb, '[{"part":"Yüzeyler","options":["Özel karbon / SiC","Karbon / TC"]},{"part":"Sekonder conta (O-ring)","options":["NBR","EPDM","FKM","FFKM","VMQ (silikon)","FEP kaplı FKM"]},{"part":"Metal parçalar","options":["AISI 316L"]}]'::jsonb, array['Kuru çalışma — bariyer sıvısı gerekmez','Ürün kontaminasyonu riski yok','Toz ve katı karıştırıcılar için uygun']::text[], array['Toz mikserleri','Gıda ve ilaç reaktörleri','Kurutucular']::text[], array[]::text[], array['EagleBurgmann SeccoMix']::text[], array['gida-ve-icecek','ilac']::text[], 'seal-agitator', false, 290) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'mikser-salmastralari'), 'ks-agmr', 'KS-AGMR', 'KS-AGMR Yan Girişli Mikser Salmastrası', 'Yan ve alttan girişli karıştırıcılar için çift kartuş mikser salmastrası.', 'KS-AGMR, yan veya alttan tahrikli karıştırıcılarda sıvı altında çalışan çift kartuş salmastradır. Mil salgısı ve eksenel kaçıklığa toleranslı tasarımı, büyük tank karıştırıcılarında güvenilir çalışma sağlar.', '[{"label":"Mil çapı (d1)","value":"30 … 200 mm"},{"label":"Basınç (p1)","value":"vakum … 14 bar"},{"label":"Bariyer basıncı (p3)","value":"≤ 16 bar · Δp = 2 … 10 bar"},{"label":"Sıcaklık (t)","value":"−20 … +200 °C"},{"label":"Kayma hızı (vg)","value":"≤ 10 m/s"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit (reçine / antimon emdirilmiş)","Silisyum karbür (SiC)","Tungsten karbür (TC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Tungsten karbür (TC)","Alümina seramik (Al₂O₃)","Karbon grafit"]},{"part":"Sekonder conta (O-ring)","options":["NBR","EPDM","FKM","FFKM","VMQ (silikon)","FEP kaplı FKM"]},{"part":"Yay ve metal parçalar","options":["AISI 316 (1.4401)","Hastelloy® C-4 (opsiyonel)"]}]'::jsonb, array['Yan ve alttan girişli karıştırıcılar','Çift kartuş','Eksenel ve radyal kaçıklık toleransı']::text[], array['Kâğıt hamuru tankları','Biyogaz fermentörleri','Büyük depolama tankları']::text[], array[]::text[], array['EagleBurgmann MR-D']::text[], array['kagit-ve-seluloz','su-ve-atik-su','kimya-ve-petrokimya']::text[], 'seal-cartridge-double', false, 300) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'oem-pompa-salmastralari'), 'ks-gf', 'KS-GF', 'KS-GF Grundfos Uyumlu Kartuş Salmastra', 'Grundfos CR, CRN, CRI ve NB/NK serisi pompalar için 12, 16 ve 22 mm mil çaplarında muadil kartuş salmastralar.', 'Grundfos CR, CRN, CRI ve NB/NK serisi pompalar için 12, 16 ve 22 mm mil çaplarında muadil kartuş salmastralar. Orijinal parça ile aynı montaj ölçülerine sahip olup doğrudan değiştirilebilir. Siparişte pompa etiketindeki model ve seri numarasını veya eski salmastranın fotoğrafını paylaşmanız yeterlidir. Marka adları yalnızca uyumluluğu belirtmek amacıyla kullanılmaktadır; ürünler ilgili üreticinin orijinal parçası değildir.', '[{"label":"Mil çapı","value":"12 mm · 16 mm · 22 mm"},{"label":"Uyumlu pompalar","value":"Grundfos CR / CRN / CRI · NB / NK serisi"},{"label":"Çalışma limitleri","value":"Pompa üreticisinin salmastra limitleri geçerlidir"}]'::jsonb, '[{"part":"Dönen yüzey","options":["Karbon grafit (reçine / antimon emdirilmiş)","Silisyum karbür (SiC)","Tungsten karbür (TC)"]},{"part":"Sabit yüzey (yatak)","options":["Silisyum karbür (SiC)","Tungsten karbür (TC)","Alümina seramik (Al₂O₃)","Karbon grafit"]},{"part":"Sekonder conta (O-ring)","options":["NBR","EPDM","FKM","FFKM","VMQ (silikon)","FEP kaplı FKM"]},{"part":"Yay ve metal parçalar","options":["AISI 316 (1.4401)","Hastelloy® C-4 (opsiyonel)"]}]'::jsonb, array['Birebir montaj ölçüsü','Orijinal malzeme kombinasyonlarına eşdeğer seçenekler','Stoktan hızlı teslimat']::text[], array['Grundfos CR / CRN / CRI','NB / NK serisi']::text[], array[]::text[], array[]::text[], array['su-ve-atik-su','gida-ve-icecek']::text[], 'seal-cartridge', false, 310) on conflict (slug) do nothing;
