insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'su-basliklari'), 'ks-rj10', 'KS-RJ10', 'KS-RJ10 Su Başlığı — Tek Akışlı', 'Soğutma ve proses suyu için tek akışlı, karbon grafit contalı döner başlık.', 'Soğutma ve proses suyu için tek akışlı, karbon grafit contalı döner başlık. Sızdırmazlık, lepleme ile düzlenmiş karbon grafit ve sert yüzey çifti ile sağlanır; tüm yıpranan parçalar yedek set olarak tedarik edilebilir. Ölçü seçimi için silindir bağlantı ölçüsü, akışkan, basınç, sıcaklık ve devir bilgisini paylaşmanız yeterlidir.', '[{"label":"Bağlantı ölçüsü","value":"3/8\" … 3\""},{"label":"Basınç","value":"≤ 10 bar"},{"label":"Sıcaklık","value":"≤ +90 °C"},{"label":"Devir","value":"≤ 1500 d/d (ölçüye bağlı)"},{"label":"Not","value":"Değerler tipik olup ölçü ve akışkana göre değişir"}]'::jsonb, '[{"part":"Gövde","options":["Dökme demir","Pirinç","AISI 316 (opsiyon)"]},{"part":"Sızdırmazlık yüzeyleri","options":["Karbon grafit","SiC","Seramik"]},{"part":"Conta","options":["NBR","FKM","PTFE","Esnek grafit"]}]'::jsonb, array['Karbon grafit yüzeyli sızdırmazlık','Kendinden yataklı yapı','Yedek parça setleri mevcuttur','Esnek hortum bağlantısı önerilir']::text[], array['Plastik ve kauçuk kalenderleri','Soğutma silindirleri','Ekstrüzyon hatları']::text[], array[]::text[], array[]::text[], array['tekstil','demir-celik']::text[], 'rotary-joint', false, 370) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'su-basliklari'), 'ks-rj12', 'KS-RJ12', 'KS-RJ12 Su Başlığı — Çift Akışlı', 'Giriş ve dönüşün aynı başlıktan yapıldığı, sabit veya dönen sifonlu çift akışlı su başlığı.', 'Giriş ve dönüşün aynı başlıktan yapıldığı, sabit veya dönen sifonlu çift akışlı su başlığı. Sızdırmazlık, lepleme ile düzlenmiş karbon grafit ve sert yüzey çifti ile sağlanır; tüm yıpranan parçalar yedek set olarak tedarik edilebilir. Ölçü seçimi için silindir bağlantı ölçüsü, akışkan, basınç, sıcaklık ve devir bilgisini paylaşmanız yeterlidir.', '[{"label":"Bağlantı ölçüsü","value":"1/2\" … 3\""},{"label":"Basınç","value":"≤ 10 bar"},{"label":"Sıcaklık","value":"≤ +90 °C"},{"label":"Devir","value":"≤ 1000 d/d"},{"label":"Not","value":"Değerler tipik olup ölçü ve akışkana göre değişir"}]'::jsonb, '[{"part":"Gövde","options":["Dökme demir","Pirinç","AISI 316 (opsiyon)"]},{"part":"Sızdırmazlık yüzeyleri","options":["Karbon grafit","SiC","Seramik"]},{"part":"Conta","options":["NBR","FKM","PTFE","Esnek grafit"]}]'::jsonb, array['Karbon grafit yüzeyli sızdırmazlık','Kendinden yataklı yapı','Yedek parça setleri mevcuttur','Esnek hortum bağlantısı önerilir']::text[], array['Soğutma silindirleri','Kalıp soğutma','Merdane soğutma']::text[], array[]::text[], array[]::text[], array['tekstil','demir-celik']::text[], 'rotary-joint-double', false, 380) on conflict (slug) do nothing;
