insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'swivel-joint'), 'ks-sj20', 'KS-SJ20', 'KS-SJ20 Dişli Swivel Joint', 'Dişli bağlantılı, tek düzlemde 360° dönen bilyalı döner mafsal.', 'KS-SJ20, çift sıra bilyalı yatak yapısıyla eksenel ve radyal yükleri taşıyarak hortum ve boru hatlarında serbest dönüş sağlar. Dolum kolları ve hortum makaralarında hattın burulmasını engeller.', '[{"label":"Bağlantı","value":"1/2\" … 4\" BSP / NPT"},{"label":"Basınç","value":"≤ PN 25"},{"label":"Sıcaklık","value":"−30 … +200 °C (conta malzemesine bağlı)"},{"label":"Gövde","value":"Karbon çelik (galvaniz) · AISI 316"}]'::jsonb, '[{"part":"Gövde","options":["Karbon çelik","AISI 316"]},{"part":"Conta","options":["NBR","FKM","PTFE","EPDM"]}]'::jsonb, array['Çift sıra bilyalı yatak','360° serbest dönüş','Değiştirilebilir contalar']::text[], array['Dolum ve boşaltım kolları','Hortum makaraları','Tank kamyonları']::text[], array[]::text[], array[]::text[], array['kimya-ve-petrokimya','gida-ve-icecek']::text[], 'swivel-joint', false, 510) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'swivel-joint'), 'ks-sj50', 'KS-SJ50', 'KS-SJ50 Flanşlı Swivel Joint', 'Flanş bağlantılı, çok düzlemde dönüş için ağır hizmet döner mafsal.', 'KS-SJ50, flanşlı bağlantısı ve güçlendirilmiş bilyalı yataklarıyla büyük çaplı hatlarda ve yükleme kollarında kullanılır. Farklı stil kombinasyonlarıyla bir, iki veya üç düzlemde hareket sağlar.', '[{"label":"Bağlantı","value":"DN 25 … DN 150 (EN 1092-1 / ASME B16.5 flanş)"},{"label":"Basınç","value":"≤ PN 40"},{"label":"Sıcaklık","value":"−30 … +200 °C"},{"label":"Gövde","value":"Karbon çelik · AISI 316"}]'::jsonb, '[{"part":"Gövde","options":["Karbon çelik","AISI 316"]},{"part":"Conta","options":["NBR","FKM","PTFE"]}]'::jsonb, array['Flanşlı bağlantı','Ağır hizmet yatakları','Çok düzlemli stiller']::text[], array['Yükleme kolları','Liman ve terminal hatları','Proses boru hatları']::text[], array['EN 1092-1','ASME B16.5']::text[], array[]::text[], array['kimya-ve-petrokimya','denizcilik']::text[], 'swivel-joint', false, 520) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'tampon-sivi-sistemleri'), 'ks-p52', 'KS-P52', 'KS-P52 Termosifon Tankı (API Plan 52 / 53A)', 'Çift salmastralar için soğutma serpantinli, seviye ve basınç göstergeli tampon/bariyer tankı.', 'KS-P52, çift mekanik salmastraların tampon (Plan 52) veya basınçlı bariyer (Plan 53A) sıvısını depolar ve termosifon etkisiyle dolaştırır. Soğutma serpantini, seviye göstergesi, basınç göstergesi ve seviye/basınç switch''leri ile donatılır.', '[{"label":"Hacim","value":"10 L · 20 L"},{"label":"Tasarım basıncı","value":"≤ 40 bar"},{"label":"Tasarım sıcaklığı","value":"−20 … +200 °C"},{"label":"Malzeme","value":"AISI 316L"}]'::jsonb, '[{"part":"Tank ve bağlantılar","options":["AISI 316L"]},{"part":"Enstrümantasyon","options":["Seviye göstergesi","Manometre","Seviye / basınç switch''i"]}]'::jsonb, array['Dahili soğutma serpantini','Termosifon dolaşımı','Enstrümantasyon seçenekleri','Duvar veya şase montajı']::text[], array['Çift mekanik salmastralar','Tandem salmastralar','Mikser salmastraları']::text[], array['API 682 Plan 52 / 53A']::text[], array[]::text[], array['kimya-ve-petrokimya','enerji']::text[], 'seal-support-vessel', false, 530) on conflict (slug) do nothing;
insert into public.products (category_id, slug, code, name, summary, description, specs, materials, features, applications, standards, equivalents, industries, illustration, is_featured, sort_order) values ((select id from public.categories where slug = 'tampon-sivi-sistemleri'), 'ks-p53b', 'KS-P53B', 'KS-P53B Akümülatörlü Bariyer Sistemi (API Plan 53B)', 'Balon akümülatörlü, kanatlı soğutuculu kapalı devre bariyer sistemi.', 'KS-P53B, bariyer sıvısını azot ön dolumlu balon akümülatör ile basınçlandırır; böylece gaz bariyer sıvısına karışmaz. Kanatlı hava soğutucu veya su soğutmalı eşanjör ile ısı uzaklaştırılır. Uzun süre dolum gerektirmeden çalışır.', '[{"label":"Akümülatör hacmi","value":"10 L · 20 L · 35 L"},{"label":"Tasarım basıncı","value":"≤ 100 bar"},{"label":"Tasarım sıcaklığı","value":"−20 … +150 °C"},{"label":"Soğutma","value":"Kanatlı hava soğutucu · su soğutmalı eşanjör"}]'::jsonb, '[{"part":"Borulama","options":["AISI 316L"]},{"part":"Balon","options":["NBR","FKM","ECO"]}]'::jsonb, array['Gaz-sıvı teması yok','Yüksek basınçlı uygulamalar','Uzun dolum aralığı','Manuel veya otomatik dolum ünitesi']::text[], array['Yüksek basınçlı çift salmastralar','Hidrokarbon pompaları','Uzak sahalar']::text[], array['API 682 Plan 53B']::text[], array[]::text[], array['kimya-ve-petrokimya','enerji']::text[], 'seal-support-vessel', false, 540) on conflict (slug) do nothing;
